/* HEXA BATTLEGROUNDS setup — PART 41 OF 80. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('airdrop-bottle-20', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":7},{"c":"green","d":2},{"c":"yellow","d":4},{"c":"purple","d":9},{"c":"orange","d":5}],"ammo":6}},"intel":{"title":"Safe order","body":"PURPLE  →  YELLOW  →  ORANGE  →  RED","big":true},"decoder":{"title":"Scramble rule","body":"Subtract each digit from 9."}}'::jsonb, '[{"label":"4-digit safe code","accept":["0546"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Purple=9 Yellow=4 Orange=5 Red=3 → 9 minus each digit → 0546', null, 25, 'published'), ('airdrop-bottle-21', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":2},{"c":"green","d":9},{"c":"yellow","d":4},{"c":"purple","d":5},{"c":"orange","d":8}],"ammo":6}},"intel":{"title":"Safe order","body":"BLUE  →  ORANGE  →  GREEN  →  RED","big":true},"decoder":{"title":"Scramble rule","body":"Keep the digits exactly as they are — no change."}}'::jsonb, '[{"label":"4-digit safe code","accept":["2893"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Blue=2 Orange=8 Green=9 Red=3 → unchanged → 2893', null, 25, 'published'), ('airdrop-bottle-22', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":6},{"c":"blue","d":0},{"c":"green","d":7},{"c":"yellow","d":1},{"c":"purple","d":9},{"c":"orange","d":3}],"ammo":6}},"intel":{"title":"Safe order","body":"ORANGE  →  PURPLE  →  RED  →  BLUE","big":true},"decoder":{"title":"Scramble rule","body":"Swap the first two digits and the last two digits."}}'::jsonb, '[{"label":"4-digit safe code","accept":["9306"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Orange=3 Purple=9 Red=6 Blue=0 → pairs swapped → 9306', null, 25, 'published'), ('airdrop-bottle-23', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":5},{"c":"blue","d":0},{"c":"green","d":7},{"c":"yellow","d":4},{"c":"purple","d":3},{"c":"orange","d":2}],"ammo":6}},"intel":{"title":"Safe order","body":"GREEN  →  PURPLE  →  YELLOW  →  ORANGE","big":true},"decoder":{"title":"Scramble rule","body":"Add 2 to every digit and keep only the last digit (9 → 1)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["9564"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Green=7 Purple=3 Yellow=4 Orange=2 → +2 to each digit → 9564', null, 25, 'published'), ('airdrop-bottle-24', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":2},{"c":"blue","d":3},{"c":"green","d":0},{"c":"yellow","d":6},{"c":"purple","d":8},{"c":"orange","d":9}],"ammo":6}},"intel":{"title":"Safe order","body":"ORANGE  →  YELLOW  →  RED  →  GREEN","big":true},"decoder":{"title":"Scramble rule","body":"Add 1 to every digit (9 becomes 0)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["0731"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Orange=9 Yellow=6 Red=2 Green=0 → +1 to each digit → 0731', null, 25, 'published'), ('airdrop-bottle-25', 'bottle', 'airdrop', 'Bottle Shoot', 'game', 1, array['any']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":5},{"c":"blue","d":0},{"c":"green","d":3},{"c":"yellow","d":9},{"c":"purple","d":1},{"c":"orange","d":7}],"ammo":6}},"intel":{"title":"Safe order","body":"YELLOW  →  GREEN  →  PURPLE  →  ORANGE","big":true},"decoder":{"title":"Scramble rule","body":"Read the digits in REVERSE order."}}'::jsonb, '[{"label":"4-digit safe code","accept":["7139"]}]'::jsonb, false, 3, 150, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Yellow=9 Green=3 Purple=1 Orange=7 → reversed → 7139', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-bottle-40', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":0},{"c":"green","d":9},{"c":"yellow","d":1},{"c":"purple","d":7},{"c":"orange","d":4}],"ammo":6}},"intel":{"title":"Safe order","body":"ORANGE  →  BLUE  →  GREEN  →  YELLOW","big":true},"decoder":{"title":"Scramble rule","body":"Swap the first two digits and the last two digits."}}'::jsonb, '[{"label":"4-digit safe code","accept":["0419"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Orange=4 Blue=0 Green=9 Yellow=1 → pairs swapped → 0419', null, 25, 'published'), ('battle-bottle-41', 'bottle', 'battle', 'Bottle Shoot Duel', 'game', 1, array['duel_smg']::text[], 'Scout is on the gun range: shoot the glass bottles — each colour hides one digit. Intel knows which colours open the safe, in order. Decoder knows how to scramble the code.', '{"scout":{"title":"Gun range","body":"Tap a bottle to shoot it. A broken bottle shows its digit; every bottle of that colour hides the same digit. 6 shots, then reload. Shout every colour and digit you find.","game":{"type":"bottle","bottles":[{"c":"red","d":3},{"c":"blue","d":6},{"c":"green","d":0},{"c":"yellow","d":8},{"c":"purple","d":1},{"c":"orange","d":7}],"ammo":6}},"intel":{"title":"Safe order","body":"GREEN  →  YELLOW  →  PURPLE  →  BLUE","big":true},"decoder":{"title":"Scramble rule","body":"Add 2 to every digit and keep only the last digit (9 → 1)."}}'::jsonb, '[{"label":"4-digit safe code","accept":["2038"]}]'::jsonb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Green=0 Yellow=8 Purple=1 Blue=6 → +2 to each digit → 2038', null, 