nb, false, 3, 75, 'Scout: call out "red is 3, blue is 7…". Intel: read the four colours in order. Decoder: apply the rule last.', 'Red=1 Yellow=5 Purple=2 Blue=9 → reversed → 9251', null, 25, 'published'), ('mission-memcards-0', 'cards', 'mission', 'Memory Cards', 'game', 1, array['any','social','coffee','food','learning','office','hr']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"♥","l":"C"},{"s":"♦","l":"D"},{"s":"♠","l":"O"},{"s":"●","l":"J"},{"s":"♠","l":"O"},{"s":"★","l":"E"},{"s":"♣","l":"Q"},{"s":"●","l":"J"},{"s":"♥","l":"C"},{"s":"♦","l":"D"},{"s":"★","l":"E"},{"s":"♣","l":"Q"}]}},"intel":{"title":"Symbol order","body":"♥   ♠   ♦   ★\n(Heart, Spade, Diamond, Star)","big":true},"decoder":{"title":"The twist","body":"Read the letters exactly as they appear."}}'::jsonb, '[{"label":"4-letter word","accept":["CODE"]}]'::jsonb, false, 3, 200, 'Match all six pairs first, then let Intel read the symbols in order and the Decoder apply the twist.', '♥=C ♠=O ♦=D ★=E → Read the letters exactly as they appear → CODE', null, 25, 'published'), ('mission-memcards-1', 'cards', 'mission', 'Memory Cards', 'game', 1, array['any','social','coffee','food','learning','office','hr']::text[], 'Scout flips cards to find matching pairs; every matched pair shows a letter. Intel knows which symbols spell the word. Decoder knows the twist.', '{"scout":{"title":"Memory Cards","body":"Tap two cards to flip them. A matching pair stays face up and shows its letter. Call out every symbol and letter.","game":{"type":"cards","deck":[{"s":"♥","l":"Z"},{"s":"♣","l":"U"},{"s":"●","l":"V"},{"s":"♥","l":"Z"},{"s":"★","l":"C"},{"s":"★","l":"C"},{"s":"♦","l":"Q"},{"s":"♠","l":"F"},{"s":"♠","l":"F"},{"s":"●","l":"V"},{"s":"♣","l":"U"},{"s":"♦","l":"Q"}]}},"intel":{"title":"Symbol order","body":"★   ♥   ♣   ♠\n(Star, Heart, Club, Spade)","big":true},"decoder":{"title":"The twist","body":"Every letter was moved ONE step forward in the alphabet. Move each letter one step BACK (B → A, A → Z)."}}'::jsonb, '[{"label":"4-letter word","accept":["BYTE"]}]'::jsonb, false, 3, 200, 'Match all six pairs first, then let Intel read the symbols in order and the Decoder apply the twist.', '★=C ♥=Z ♣=U ♠=F → Every letter was moved ONE step forward in the alphabet → BYTE', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
